// Pure function: Easy to test, no side effects
function calculateTotal(items, taxRate) {
  const subtotal = items.reduce((sum, item) => sum + item.price, 0);
  const tax = subtotal * taxRate;
  return subtotal + tax;
}

// Unit test: Fast, isolated, deterministic
test('calculates total with tax correctly', () => {
  // Arrange
  const items = [
    { name: 'Book', price: 29.99 },
    { name: 'Pen', price: 2.99 }
  ];
  const taxRate = 0.08; // 8%

  // Act
  const result = calculateTotal(items, taxRate);

  // Assert
  // 29.99 + 2.99 = 32.98 subtotal
  // 32.98 * 0.08 = 2.6384 tax
  // 32.98 + 2.6384 = 35.6184 total
  expect(result).toBeCloseTo(35.62, 2);
});

