      expect(email.subject).toContain('Trade Confirmation');

      // Verify analytics tracking
      const analytics = await confirmationPage.getAnalyticsEvent('trade_completed');
      expect(analytics.userId).toBe(user.email);
      expect(analytics.properties.amount).toBe(investment.amount);

      // Verify audit trail
      const auditLog = await confirmationPage.getAuditLog();
      expect(auditLog.action).toBe('trade_execution');
      expect(auditLog.status).toBe('success');
    });
  });
