describe('User Registration Exploration', () => {
  test('valid registration flow', async () => {
    // Basic happy path
    await registerUser(validUser);
    await expectRegistrationSuccess();
  });

  test('boundary conditions for username', async () => {
    // Explore username boundaries
    const edgeCases = [
      { username: 'a'.repeat(1), expected: 'valid' }, // Minimum length
      { username: 'a'.repeat(50), expected: 'valid' }, // Maximum length
      { username: 'a'.repeat(51), expected: 'error' }, // Exceeds maximum
      { username: 'user name', expected: 'valid' }, // Contains space
      { username: 'user@name', expected: 'error' }, // Special character
      { username: '123username', expected: 'valid' }, // Starts with number
      { username: 'admin', expected: 'error' }, // Reserved username
    ];

    for (const { username, expected } of edgeCases) {
      await test.step(`Username: ${username.substring(0, 20)}`, async () => {
        const result = await attemptRegistration({ ...validUser, username });
        if (expected === 'valid') {
          expect(result.success).toBe(true);
        } else {
          expect(result.error).toBeDefined();
        }
      });
    }
  });

  test('race conditions and concurrency', async () => {
    // Test simultaneous registration attempts
    const promises = [];
    for (let i = 0; i < 5; i++) {
      const user = { ...validUser, username: `user${i}` };
      promises.push(registerUser(user));
    }

    const results = await Promise.all(promises);
    // Verify all registrations succeeded
    expect(results.every(r => r.success)).toBe(true);

    // Try registering same username concurrently
    const duplicatePromises = [
      registerUser({ ...validUser, username: 'duplicate' }),
      registerUser({ ...validUser, username: 'duplicate' })
    ];

    const duplicateResults = await Promise.allSettled(duplicatePromises);
    // Only one should succeed, one should fail
    const successCount = duplicateResults.filter(r => r.status === 'fulfilled').length;
    expect(successCount).toBe(1);
  });

  test('state persistence and cleanup', async () => {
    // Register user
    await registerUser(validUser);

